def compute(vars):
    beginning_balance = vars["v1"]
    ending_balance = vars["v2"]
    net_change = ending_balance - beginning_balance

    return {
        "value": net_change,
        "trace": {
            "beginning_balance": beginning_balance,
            "ending_balance": ending_balance,
            "net_change": net_change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
